-- LOCAL disposable only. Tariff17 is an arbitrary test fixture, not product pricing.
reset role;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
create temp table aa_state(key text primary key,value jsonb);grant all on aa_state to authenticated,service_role,anon;
insert into private.prisma_token_rates(function_name,tokens_per_unit) values('assessment_activity_analysis',17);
insert into public.position_assessment_attempts(id,organization_id,assessment_id,token_hash,expires_at,status,started_at)
 select m83_id('aa-attempt'),m83_id('a'),a.id,repeat('c',64),now()+interval '1 day','started',now() from public.position_assessments a where a.organization_id=m83_id('a') and a.person_id is not null and jsonb_array_length(a.questions)>0 limit 1;
insert into public.position_assessment_events(organization_id,attempt_id,event_id,question_id,question_version,kind,client_at_ms,sequence,method,payload)
 select m83_id('a'),m83_id('aa-attempt'),m83_id('aa-event'),(a.questions#>>'{0,id}')::uuid,a.questions#>>'{0,version}','focus_episode',1791894360000,0,'position-assessment-focus-1.0.0','{"durationMs":7000,"closedBy":"focus_returned"}' from public.position_assessment_attempts t join public.position_assessments a on a.id=t.assessment_id where t.id=m83_id('aa-attempt');
create temp table aa_preserved as select (select jsonb_agg(to_jsonb(x) order by id) from public.position_assessment_attempts x) attempts,(select jsonb_agg(to_jsonb(x) order by id) from public.position_assessment_events x) events;
set local role anon;
select m83_reject('select public.assessment_activity_analysis_load(m83_id(''a''),m83_id(''aa-attempt''))','42501');
select m83_reject('select public.assessment_activity_analysis_start(m83_id(''a''),m83_id(''aa-attempt''),m83_id(''aa-request''),null)','42501');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('member')::text,true);
select m83_reject('select public.assessment_activity_analysis_load(m83_id(''a''),m83_id(''aa-attempt''))','42501');
select set_config('request.jwt.claim.sub',m83_id('inactive')::text,true);
select m83_reject('select public.assessment_activity_analysis_load(m83_id(''a''),m83_id(''aa-attempt''))','42501');
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_reject('select public.assessment_activity_analysis_load(m83_id(''b''),m83_id(''aa-attempt''))','42501');
select m83_reject('select public.assessment_activity_analysis_load(m83_id(''a''),m83_id(''missing''))','42501');
select m83_reject('select * from private.assessment_activity_analyses','42501');
select m83_reject('select private.assessment_activity_snapshot(m83_id(''a''),m83_id(''aa-attempt''))','42501');
select m83_reject('select public.assessment_activity_analysis_finish(m83_id(''a''),m83_id(''aa-request''),true,''{}'',''{}'',''{}'')','42501');
insert into aa_state values('load',public.assessment_activity_analysis_load(m83_id('a'),m83_id('aa-attempt')));
select m83_assert((select value->'analysis'='null' and value->>'contract'='assessment-activity-analysis-1.0.0' from aa_state where key='load'),'free load contains scope and no result or generation');
select m83_reject('select public.assessment_activity_analysis_start(m83_id(''a''),m83_id(''aa-attempt''),m83_id(''aa-request''),null)','42501');
insert into aa_state values('quote',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
select m83_assert((select value->>'amount'='17' from aa_state where key='quote'),'new category uses configured server tariff, no inferred price');
insert into aa_state values('start',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-request'),(select (value->>'id')::uuid from aa_state where key='quote')));
select m83_assert((select (value->>'acquired')::boolean and value#>>'{snapshot,questions,0,id}' is not null and not(value::text like '%full_name%') from aa_state where key='start'),'authorized start reserves before returning official snapshot, without name or answers');
insert into aa_state values('same',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-request'),null));
select m83_assert((select value->>'acquired'='false' from aa_state where key='same'),'same operation cannot acquire provider twice');
insert into aa_state values('other',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-other'),null));
select m83_assert((select value->>'acquired'='false' from aa_state where key='other'),'same snapshot with other request reuses active operation without quote or debit');
reset role;
select m83_assert((select count(*)=1 and min(amount)=17 from private.prisma_token_reservations where function_name='assessment_activity_analysis'),'exactly one commercial reservation');
select m83_assert((select count(*)=1 from public.ai_requests where function_name='assessment_activity_analysis'),'generic AI history reused, no prompts in metadata');
insert into aa_state values('facts',jsonb_build_object('contract','assessment-activity-analysis-1.0.0','questionCount',(select jsonb_array_length(value#>'{snapshot,questions}') from aa_state where key='start'),'patterns',jsonb_build_array(jsonb_build_object('id','focus_occurrences','title','Perda de foco registrada'))));
set local role service_role;select set_config('request.jwt.claims',jsonb_build_object('role','service_role','sub',m83_id('recruiter'))::text,true);
select m83_reject('select public.assessment_activity_analysis_finish(m83_id(''b''),m83_id(''aa-request''),true,''{}'',''{}'',''{}'')','42501');
select m83_reject('select public.assessment_activity_analysis_finish(m83_id(''a''),m83_id(''aa-request''),true,''{}'',''{}'',''{}'')','22023');
insert into aa_state values('finish',public.assessment_activity_analysis_finish(m83_id('a'),m83_id('aa-request'),true,(select value from aa_state where key='facts'),'{"patternIds":["focus_occurrences"],"contextIds":["focus","missing"]}','{"durationMs":20,"inputTokens":100,"outputTokens":20,"estimatedCostUsd":0.0001}'));
select m83_assert((select value->>'status'='succeeded' from aa_state where key='finish'),'valid result persisted');
select public.assessment_activity_analysis_finish(m83_id('a'),m83_id('aa-request'),true,(select value from aa_state where key='facts'),'{"patternIds":["focus_occurrences"],"contextIds":["focus","missing"]}','{"durationMs":20,"inputTokens":100,"outputTokens":20,"estimatedCostUsd":0.0001}');
select m83_reject('select public.assessment_activity_analysis_finish(m83_id(''a''),m83_id(''aa-request''),false,null,null,''{"durationMs":20}'')','40001');
reset role;select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',m83_id('recruiter'))::text,true);set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
insert into aa_state values('cache',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-cache'),null));
select m83_assert((select value->>'acquired'='false' and value#>>'{analysis,status}'='succeeded' from aa_state where key='cache'),'saved result consultation needs no quote, provider or debit');
reset role;
select m83_assert((select count(*)=1 from private.prisma_token_movements where function_name='assessment_activity_analysis' and kind='debit'),'completion replay cannot debit twice');
select m83_assert((select sum(estimated_cost_usd)=0.0001 from public.ai_usage_events e join public.ai_requests r on r.id=e.request_id where r.function_name='assessment_activity_analysis'),'provider technical cost remains separate');
insert into public.position_assessment_events(organization_id,attempt_id,event_id,question_id,question_version,kind,client_at_ms,sequence,method,payload)
 select m83_id('a'),m83_id('aa-attempt'),m83_id('aa-event-two'),(a.questions#>>'{0,id}')::uuid,a.questions#>>'{0,version}','question_reopened',1791894360100,1,'fixture','{}' from public.position_assessment_attempts t join public.position_assessments a on a.id=t.assessment_id where t.id=m83_id('aa-attempt');
set local role authenticated;
insert into aa_state values('stale',public.assessment_activity_analysis_load(m83_id('a'),m83_id('aa-attempt')));
select m83_assert((select (value#>>'{analysis,stale}')::boolean from aa_state where key='stale'),'new events mark old report stale without generation');
insert into aa_state values('quote-two',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
insert into aa_state values('start-two',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-fail'),(select (value->>'id')::uuid from aa_state where key='quote-two')));
reset role;set local role service_role;select set_config('request.jwt.claims',jsonb_build_object('role','service_role','sub',m83_id('recruiter'))::text,true);
select public.assessment_activity_analysis_finish(m83_id('a'),m83_id('aa-fail'),false,null,null,'{"durationMs":10,"inputTokens":100,"outputTokens":20,"estimatedCostUsd":0.0001}');
reset role;
select m83_assert((select status='released' from private.prisma_token_reservations where operation_id=m83_id('aa-fail')),'failed result releases commercial tokens while retaining technical usage');
select m83_assert((select count(*)=1 from private.prisma_token_movements where function_name='assessment_activity_analysis' and kind='debit'),'failed second analysis does not debit');
set local role authenticated;select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',m83_id('recruiter'))::text,true);
insert into aa_state values('after-fail',public.assessment_activity_analysis_load(m83_id('a'),m83_id('aa-attempt')));
select m83_assert((select value#>>'{analysis,status}'='failed' and value#>>'{previousAnalysis,status}'='succeeded' from aa_state where key='after-fail'),'failed newer report retains previous successful result');
reset role;
-- Original attempt rows are identical; original events still exist unchanged, only our synthetic append is extra.
select m83_assert((select attempts=(select jsonb_agg(to_jsonb(x) order by id) from public.position_assessment_attempts x) from aa_preserved),'answers/results/attempt snapshots unchanged');
select m83_assert(((select count(*) from aa_preserved p,jsonb_array_elements(p.events) old where exists(select 1 from public.position_assessment_events e where to_jsonb(e)=old))=(select jsonb_array_length(events) from aa_preserved)),'original activity events preserved');
select m83_assert((select relrowsecurity from pg_class where oid='private.assessment_activity_analyses'::regclass),'new table RLS enabled');

set local role authenticated;
insert into aa_state values('quote-uncertain',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
insert into aa_state values('start-uncertain',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-uncertain'),(select (value->>'id')::uuid from aa_state where key='quote-uncertain')));
reset role;
update private.assessment_activity_analyses set created_at=clock_timestamp()-interval '3 minutes' where id=m83_id('aa-uncertain');
set local role authenticated;
select m83_assert(public.assessment_activity_analysis_load(m83_id('a'),m83_id('aa-attempt'))#>>'{analysis,status}'='reconciliation_required','uncertain timeout never triggers automatic paid retry');
reset role;
select private.prisma_token_settle(m83_id('a'),'assessment_activity_analysis',m83_id('aa-uncertain'),false,'Synthetic explicit administrator release');
set local role authenticated;
select m83_assert(public.assessment_activity_analysis_load(m83_id('a'),m83_id('aa-attempt'))#>>'{analysis,status}'='failed','explicit release becomes visible to caller without automatic work');
insert into aa_state values('quote-retry',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
insert into aa_state values('start-retry',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('aa-after-release'),(select (value->>'id')::uuid from aa_state where key='quote-retry')));
select m83_assert((select value->>'acquired'='true' from aa_state where key='start-retry'),'new paid attempt requires new explicit quoted operation after administrative release');
reset role;
select m83_assert((select status='failed' from public.ai_requests where operation_id=m83_id('aa-uncertain') and function_name='assessment_activity_analysis'),'released uncertainty closes generic history with unknown technical cost');
set local role service_role;select set_config('request.jwt.claims',jsonb_build_object('role','service_role')::text,true);
select public.assessment_activity_analysis_finish(m83_id('a'),m83_id('aa-after-release'),false,null,null,'{"durationMs":10,"inputTokens":null,"outputTokens":null,"estimatedCostUsd":null}');
reset role;select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',m83_id('recruiter'))::text,true);
